recipe.compute:
function compute(input) {
  const outline = input.r1;
  if (!outline || !outline.chapters) {
    return { missing: true, message: '无法获取月报大纲' };
  }
  const chapters = outline.chapters
    .filter(c => c.numbered)
    .map(c => ({
      label: c.title,
      anchor: c.anchor,
      no: c.no
    }));
  return { chapters };
}

recipe.render:
function render(result, kit) {
  if (result.missing) return kit.text(result.message);
  return kit.nav(result.chapters, { columns: 4 });
}
